CREATE TEMP TABLE expanded_subtopics (
  slug TEXT PRIMARY KEY,
  topic_slug TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  theory TEXT NOT NULL,
  illustration_key TEXT NOT NULL,
  sort_order INTEGER NOT NULL
);

INSERT INTO expanded_subtopics VALUES
('mdp-policy-return','mdp','Возврат, эпизоды и стратегия','Как последовательность шагов превращается в суммарную награду и почему стратегия определяет поведение агента.',
$$В MDP агент не оценивает отдельное действие само по себе. Важен весь последующий путь: какие состояния будут посещены, какие награды появятся позже и насколько далеко вперед агент должен смотреть. Поэтому в обучении с подкреплением вводят понятие возврата G_t - суммарной дисконтированной награды от текущего момента до конца эпизода или на бесконечном горизонте.

Возврат записывают как G_t = R_{t+1} + gamma R_{t+2} + gamma^2 R_{t+3} + ... . Коэффициент gamma уменьшает вклад отдаленных наград. Если gamma близок к нулю, агент ведет себя почти жадно и реагирует на ближайший результат. Если gamma близок к единице, агент учитывает долгосрочные последствия.

Эпизод - это законченная траектория взаимодействия: например, партия игры, проход лабиринта или попытка удержать баланс робота. В эпизодической задаче есть терминальное состояние. В непрерывной задаче явного конца может не быть, поэтому возврат считают на бесконечном горизонте с дисконтированием.

Стратегия pi описывает, как агент выбирает действие в состоянии. Она может быть детерминированной, когда каждому состоянию соответствует одно действие, или стохастической, когда действия выбираются с вероятностями. В реальном обучении стохастическая стратегия полезна: она оставляет место исследованию и не застревает слишком рано в случайно найденном варианте.

Пример: в лабиринте стратегия, которая всегда идет к ближайшей монете, может получить быстрые небольшие награды, но не найти выход. Стратегия с большим учетом будущего способна отказаться от короткого выигрыша ради более крупной конечной награды.$$,'return-episode',3),
('mdp-model-free-model-based','mdp','Модельные и безмодельные задачи','Различие между алгоритмами, которые знают модель среды, и алгоритмами, которые учатся только по опыту.',
$$В обучении с подкреплением модель среды - это описание того, как среда переходит из состояния в состояние и какие награды выдает. Если агент знает P(s'|s,a) и R(s,a,s'), он может планировать: мысленно просчитывать последствия действий и выбирать лучший вариант до реального шага.

Модельные методы используют это знание. Классические примеры - итерация по стратегиям и итерация по ценности. Они перебирают состояния, применяют уравнения Беллмана и постепенно находят оптимальную стратегию. Такие методы хорошо объясняют теорию, но требуют явной модели и обычно плохо масштабируются на огромные пространства состояний.

Безмодельные методы не знают правил среды заранее. Они получают опыт в виде переходов (s, a, r, s') и обновляют оценки по наблюдениям. Q-learning, SARSA и многие deep RL методы относятся к этому классу. Их преимущество в том, что можно учиться в симуляторе или реальной среде без таблицы всех вероятностей.

Есть и смешанные подходы. Агент может строить приближенную модель по опыту, а затем использовать ее для планирования. Эта идея важна в Dyna-подходах: реальные переходы попадают в память, по ним обучается модель, а затем агент дополнительно тренируется на сгенерированных моделью переходах.

Главный выбор такой: если модель среды известна и небольшая, выгодны модельные методы; если среда сложная, неизвестная или поступает как черный ящик, чаще используют безмодельное обучение.$$,'model-types',4),
('q-learning-parameters','q-learning','Параметры alpha, gamma и epsilon','Как скорость обучения, дисконтирование и исследование меняют поведение Q-learning.',
$$В Q-learning качество обучения сильно зависит от трех параметров: alpha, gamma и epsilon. Они отвечают за разные стороны процесса и вместе задают стиль поведения агента.

Alpha - скорость обучения. Она показывает, насколько сильно новая TD-цель меняет старое значение Q(s,a). При большом alpha агент быстро реагирует на свежий опыт, но оценки могут колебаться. При маленьком alpha обучение стабильнее, но требует больше эпизодов.

Gamma - коэффициент дисконтирования. Он определяет, насколько агент ценит будущие награды. В задачах с долгосрочной целью gamma обычно выбирают высоким, например 0.9 или 0.99. Если награды локальные и будущее мало важно, gamma можно уменьшить.

Epsilon - вероятность исследования в epsilon-жадной стратегии. С вероятностью epsilon агент выбирает случайное действие, а с вероятностью 1 - epsilon использует лучшее действие по текущей Q-таблице. На практике epsilon часто уменьшают: в начале агент активно исследует, а после накопления опыта чаще использует найденную стратегию.

Ошибки настройки типичны. Слишком маленький epsilon может привести к раннему застреванию. Слишком большой epsilon не дает стабильно использовать хорошую стратегию. Слишком высокий alpha делает обучение нервным, а слишком низкий - медленным. Поэтому параметры подбирают под среду и проверяют по кривой награды.$$,'q-parameters',3),
('q-learning-practice','q-learning','Практический алгоритм Q-learning','Пошаговая схема табличного Q-learning для учебной среды.',
$$Табличный Q-learning удобно начинать с небольшой среды: лабиринта, grid world или простой игры с дискретными действиями. Для каждой пары состояние-действие хранится число Q(s,a), которое оценивает ожидаемый возврат при выборе действия a в состоянии s.

Алгоритм начинается с инициализации Q-таблицы. Часто все значения ставят равными нулю, но иногда используют оптимистичную инициализацию, чтобы стимулировать исследование. Затем запускаются эпизоды. В каждом эпизоде агент наблюдает текущее состояние, выбирает действие через epsilon-жадную стратегию, получает награду и новое состояние.

После каждого перехода выполняется обновление: Q(s,a) = Q(s,a) + alpha [ r + gamma max_a' Q(s',a') - Q(s,a) ]. Здесь r + gamma max Q - целевая оценка, а разница между целью и текущим Q - TD-ошибка. Обновление постепенно переносит информацию о будущих наградах назад по траекториям.

Практически важно следить не только за итоговой наградой, но и за длиной эпизода, числом случайных действий, распределением посещенных состояний и стабильностью политики. Если агент перестал исследовать часть карты, Q-таблица может выглядеть уверенно, но быть неполной.

Когда Q-значения стабилизируются, из таблицы извлекают стратегию: в каждом состоянии выбирают действие с максимальным Q. Для дипломного сайта такой алгоритм хорошо подходит как базовый пример, потому что его можно объяснить таблицей, шагами и простым тестом.$$,'q-practice',4),
('sarsa-on-policy','sarsa','On-policy обучение и безопасность','Почему SARSA учитывает реальное поведение агента, включая исследовательские действия.',
$$SARSA относится к on-policy методам. Это значит, что она оценивает ту же стратегию, по которой агент действительно действует. В обновлении используется не максимум по всем действиям в следующем состоянии, а следующее действие A', выбранное текущей стратегией.

Название SARSA складывается из последовательности: State, Action, Reward, State, Action. Агент наблюдает S, выбирает A, получает R и S', затем выбирает A' по той же epsilon-жадной стратегии. После этого обновляется Q(S,A) на основе Q(S',A').

Такой подход делает SARSA более осторожной в задачах, где исследование может быть опасным. Если стратегия иногда выбирает случайные действия, SARSA учитывает риск этих случайных действий в своих оценках. Q-learning, наоборот, смотрит на лучший возможный следующий ход и может переоценивать траектории рядом с опасными областями.

Пример - движение около обрыва. Кратчайший путь проходит рядом с опасной зоной, но случайный шаг может привести к большому штрафу. SARSA обычно выбирает более безопасный маршрут, потому что ее оценка включает вероятность исследовательского промаха.

On-policy обучение особенно полезно, когда важно качество поведения во время самого обучения, а не только финальная оптимальная стратегия после миллионов попыток.$$,'on-policy-safety',3),
('sarsa-cliff-walking','sarsa','Пример Cliff Walking','Классическая задача, показывающая разницу между SARSA и Q-learning.',
$$Cliff Walking - учебная grid world задача. Агент стартует в нижнем левом углу, цель находится в нижнем правом углу, а клетки между ними считаются обрывом. Попадание в обрыв дает большой штраф и возвращает агента к старту.

Оптимальный кратчайший путь проходит прямо вдоль обрыва. Если агент всегда выбирает идеальные действия, это лучший маршрут. Но во время обучения используется исследование: иногда агент делает случайный шаг. Поэтому путь вдоль обрыва рискован.

Q-learning учится off-policy. Его целевое обновление предполагает, что в следующем состоянии будет выбран лучший ход. Из-за этого он часто стремится к кратчайшему маршруту рядом с обрывом. SARSA учится on-policy и учитывает, что следующая стратегия все еще epsilon-жадная. Поэтому она предпочитает более длинный, но безопасный путь.

Эта задача хорошо показывает, что "оптимальность" зависит от постановки. Если оценивается финальная жадная политика без исследования, Q-learning может выглядеть лучше. Если важна награда во время обучения и риск случайных действий, SARSA часто выигрывает.

Для учебного интерфейса Cliff Walking полезен как визуальный пример: можно показать старт, цель, опасные клетки и две разные траектории.$$,'cliff-walking',4),
('dqn-preprocessing','dqn','Предобработка состояний','Как изображения и признаки подготавливают перед подачей в DQN.',
$$DQN часто работает с высокоразмерными состояниями, например с кадрами игры. Сырые изображения содержат много лишней информации: цветовые детали, фон, повторяющиеся кадры и шум. Поэтому перед нейронной сетью обычно выполняют предобработку.

Для игр Atari классический подход включает перевод кадра в оттенки серого, уменьшение разрешения, нормализацию пикселей и объединение нескольких последних кадров в стек. Стек нужен, потому что один кадр не всегда показывает скорость объекта. Например, положение мяча видно сразу, а направление движения понятно только по нескольким кадрам.

Предобработка снижает размер входа и делает обучение устойчивее. Нейросети проще выделять важные признаки, когда вход компактный и стандартизированный. Это не просто техническая деталь: плохая предобработка может сделать задачу почти нерешаемой или резко увеличить время обучения.

В задачах не с изображениями предобработка тоже важна. Признаки нормализуют, категориальные переменные кодируют, выбросы обрабатывают, а иногда добавляют историю наблюдений. Главный принцип - состояние должно содержать информацию, достаточную для принятия решения.

Если состояние не обладает марковским свойством, агент может путаться: одинаковое наблюдение будет требовать разных действий в зависимости от скрытой истории. В таких случаях добавляют память, стек кадров или рекуррентные сети.$$,'state-preprocessing',3),
('dqn-improvements','dqn','Double и Dueling DQN','Расширения DQN, уменьшающие переоценку и улучшающие структуру Q-функции.',
$$Базовый DQN стал важным шагом, но у него есть проблемы: переоценка Q-значений, нестабильность обучения и неэффективное представление ценности действий. Поэтому появились улучшения, которые часто используют в deep RL.

Double DQN уменьшает переоценку. В обычном DQN один и тот же максимум выбирает действие и оценивает его значение. Из-за шума нейросеть может завышать лучшие действия. Double DQN разделяет выбор и оценку: online-сеть выбирает действие, а target-сеть оценивает его Q-значение. Это делает цель менее оптимистичной.

Dueling DQN меняет архитектуру сети. Вместо прямого выхода Q(s,a) сеть отдельно оценивает ценность состояния V(s) и преимущество действия A(s,a), а затем объединяет их. Это полезно в состояниях, где многие действия почти одинаковы: сеть может понять, что само состояние хорошее, не переоценивая каждое действие отдельно.

Эти методы не заменяют replay buffer и target network, а дополняют их. На практике улучшенные варианты DQN часто объединяют несколько идей: Double, Dueling, prioritized replay, многошаговые цели и нормализацию.

Для дипломного сайта важно показать, что deep RL - это не только "нейросеть вместо таблицы", а набор инженерных приемов для устойчивого обучения по последовательному опыту.$$,'dqn-improvements',4),
('actor-critic-policy-gradient','actor-critic','Градиент стратегии','Как actor улучшается напрямую через вероятность выбранных действий.',
$$В методах градиента стратегии обучается не таблица ценностей, а сама стратегия pi(a|s). Actor задает распределение вероятностей действий, а обучение изменяет параметры так, чтобы хорошие действия становились вероятнее.

Базовая идея: если действие привело к высокому возврату, вероятность такого действия в похожем состоянии нужно увеличить. Если результат оказался плохим, вероятность уменьшают. Формально это выражается через градиент ожидаемого возврата по параметрам стратегии.

Недостаток простого REINFORCE-подхода - высокая дисперсия оценок. Возврат может сильно шуметь, особенно в длинных эпизодах. Поэтому вводят baseline, чаще всего функцию ценности V(s). Тогда обновление использует не весь возврат, а преимущество: насколько действие лучше среднего ожидания для состояния.

Actor-critic соединяет эти идеи. Critic оценивает V(s) или Q(s,a), а actor использует эту оценку как обучающий сигнал для изменения стратегии. Это делает обучение более стабильным, чем чистый Monte Carlo градиент стратегии.

Градиент стратегии особенно важен для непрерывных действий: например, управление силой мотора, углом поворота или скоростью. Там трудно выбирать действие через максимум по таблице, зато можно обучать параметризованное распределение действий.$$,'policy-gradient',3),
('actor-critic-ppo-a2c','actor-critic','A2C и PPO','Популярные actor-critic алгоритмы и идея стабильного обновления политики.',
$$A2C и PPO - два известных представителя actor-critic семейства. Они используют общую идею: actor отвечает за выбор действия, critic оценивает состояние, а преимущество помогает понять, было ли действие лучше ожидаемого.

A2C расшифровывается как Advantage Actor-Critic. Он обучает actor по оценке преимущества A(s,a), а critic - по ошибке предсказания ценности. В отличие от асинхронного A3C, A2C обычно собирает опыт несколькими средами синхронно, что проще реализовать и стабильнее для учебного объяснения.

PPO - Proximal Policy Optimization. Его ключевая идея в том, чтобы не менять стратегию слишком резко. Если новая политика слишком сильно отличается от старой, обучение может разрушить уже найденное поведение. PPO ограничивает размер обновления через специальную clipped objective, благодаря чему стал популярным практическим алгоритмом.

В обоих методах важны баланс исследования, нормализация преимуществ, качество функции ценности и выбор горизонта сбора опыта. Они хорошо подходят для задач с большими или непрерывными пространствами действий, где табличные методы и DQN менее удобны.

Для учебного курса A2C можно рассматривать как понятную базовую схему actor-critic, а PPO - как практическое улучшение, которое делает обновления политики более осторожными.$$,'a2c-ppo',4);

INSERT INTO subtopics (topic_id, slug, name, description, theory_content, illustration_key, sort_order)
SELECT topics.id, expanded_subtopics.slug, expanded_subtopics.name, expanded_subtopics.description, expanded_subtopics.theory, expanded_subtopics.illustration_key, expanded_subtopics.sort_order
FROM expanded_subtopics
JOIN topics ON topics.slug = expanded_subtopics.topic_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  theory_content = EXCLUDED.theory_content,
  illustration_key = EXCLUDED.illustration_key,
  sort_order = EXCLUDED.sort_order;

INSERT INTO tests (topic_id, subtopic_id, title, passing_score)
SELECT topics.id, subtopics.id, 'Тест: ' || subtopics.name, 70
FROM expanded_subtopics
JOIN topics ON topics.slug = expanded_subtopics.topic_slug
JOIN subtopics ON subtopics.slug = expanded_subtopics.slug
WHERE NOT EXISTS (SELECT 1 FROM tests WHERE tests.subtopic_id = subtopics.id);

CREATE TEMP TABLE expanded_questions (
  subtopic_slug TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  question_text TEXT NOT NULL,
  correct TEXT NOT NULL,
  wrong_1 TEXT NOT NULL,
  wrong_2 TEXT NOT NULL,
  wrong_3 TEXT NOT NULL,
  PRIMARY KEY (subtopic_slug, sort_order)
);

INSERT INTO expanded_questions VALUES
('mdp-policy-return',1,'Что показывает возврат G_t?','Суммарную дисконтированную награду от текущего момента','Только последнюю полученную награду','Количество состояний в среде','Размер Q-таблицы'),
('mdp-policy-return',2,'Для чего используется gamma?','Чтобы уменьшать вклад отдаленных наград','Чтобы выбирать случайное действие','Чтобы удалять плохие состояния','Чтобы задавать число эпизодов'),
('mdp-policy-return',3,'Что такое эпизод?','Законченная траектория взаимодействия со средой','Один параметр нейросети','Одна строка таблицы Q','Список всех возможных действий'),
('mdp-policy-return',4,'Что задает стратегия pi?','Правило выбора действий в состояниях','Вероятность перехода среды','Формат хранения тестов','Максимальное число наград'),
('mdp-policy-return',5,'Почему стохастическая стратегия полезна при обучении?','Она помогает исследовать разные действия','Она запрещает случайные действия','Она делает gamma равным нулю','Она заменяет функцию награды'),
('mdp-model-free-model-based',1,'Что содержит модель среды в MDP?','Переходы и награды','Только имя агента','Только список тестов','Только интерфейс сайта'),
('mdp-model-free-model-based',2,'Какой метод считается безмодельным?','Q-learning','Итерация по ценности с известной моделью','Полный перебор P(s''|s,a)','Ручное задание всех переходов'),
('mdp-model-free-model-based',3,'Когда удобны модельные методы?','Когда известны переходы и награды среды','Когда нельзя наблюдать состояния','Когда нет пространства действий','Когда запрещено планирование'),
('mdp-model-free-model-based',4,'Что используют безмодельные методы?','Опыт переходов (s,a,r,s'')','Только заранее заданную таблицу вероятностей','Только текстовые статьи','Только итоговую оценку пользователя'),
('mdp-model-free-model-based',5,'Что делает Dyna-подход?','Сочетает опыт, модель и планирование','Полностью удаляет награды','Запрещает обучение по симуляции','Использует только случайные действия'),
('q-learning-parameters',1,'За что отвечает alpha?','За силу изменения Q-значения при обновлении','За размер экрана','За число действий в состоянии','За название темы'),
('q-learning-parameters',2,'Что делает epsilon?','Задает вероятность исследовательского действия','Уменьшает размер состояния','Хранит итоговый балл теста','Заменяет награду'),
('q-learning-parameters',3,'Что произойдет при слишком маленьком epsilon в начале?','Агент может рано застрять в плохой стратегии','Агент обязательно найдет все состояния','Q-таблица перестанет существовать','Gamma станет равной единице'),
('q-learning-parameters',4,'Когда обычно выбирают высокий gamma?','Когда важны долгосрочные последствия','Когда важна только мгновенная награда','Когда нет эпизодов','Когда действия непрерывны'),
('q-learning-parameters',5,'Почему alpha не всегда делают большим?','Большие обновления могут быть нестабильными','Большой alpha отключает обучение','Большой alpha удаляет состояния','Большой alpha делает действия невозможными'),
('q-learning-practice',1,'Что хранится в Q-таблице?','Оценки пар состояние-действие','Только имена пользователей','Только номера эпизодов','Только изображения среды'),
('q-learning-practice',2,'Как выбирается действие в учебном Q-learning?','Часто через epsilon-жадную стратегию','Только по алфавиту','Только случайно без учета Q','Только по последней награде'),
('q-learning-practice',3,'Что такое TD-ошибка в обновлении Q-learning?','Разница между целевой и текущей Q-оценкой','Количество строк в таблице','Номер текущей темы','Вероятность регистрации'),
('q-learning-practice',4,'Зачем смотреть на длину эпизода?','Она помогает понять, стал ли путь эффективнее','Она заменяет тестовые вопросы','Она задает пароль пользователя','Она всегда равна числу действий'),
('q-learning-practice',5,'Как извлекают финальную стратегию из Q-таблицы?','Выбирают действие с максимальным Q в каждом состоянии','Удаляют все ненулевые Q','Берут случайное действие навсегда','Сортируют состояния по названию'),
('sarsa-on-policy',1,'Что значит on-policy для SARSA?','Оценивается та стратегия, по которой агент реально действует','Оценивается только оптимальная стратегия без исследования','Среда обязана быть известной заранее','Награды не используются'),
('sarsa-on-policy',2,'Какая последовательность дала название SARSA?','State, Action, Reward, State, Action','State, Agent, Result, Score, Action','Search, Action, Replay, State, Agent','Score, Alpha, Reward, Step, Algorithm'),
('sarsa-on-policy',3,'Почему SARSA может быть осторожнее Q-learning?','Она учитывает риск исследовательских действий','Она всегда запрещает движение','Она не использует epsilon','Она выбирает только худшие действия'),
('sarsa-on-policy',4,'Что используется в цели SARSA?','Q(S'',A''), где A'' выбрано текущей стратегией','max Q(S'',a) без учета политики','Только первая награда эпизода','Среднее всех пользователей'),
('sarsa-on-policy',5,'Где on-policy подход особенно полезен?','Когда важно поведение во время обучения','Когда награды полностью отсутствуют','Когда нет действий','Когда состояние всегда одно'),
('sarsa-cliff-walking',1,'Что показывает Cliff Walking?','Разницу между рискованным кратким и безопасным длинным путем','Только работу нейросети DQN','Только регистрацию пользователя','Только непрерывные действия'),
('sarsa-cliff-walking',2,'Почему путь вдоль обрыва рискован?','Случайное исследовательское действие может привести к штрафу','Потому что gamma всегда равен нулю','Потому что там нет состояний','Потому что Q-таблица запрещена'),
('sarsa-cliff-walking',3,'Как обычно ведет себя SARSA в этой задаче?','Чаще выбирает более безопасный маршрут','Всегда падает в обрыв','Игнорирует награды','Не обновляет Q'),
('sarsa-cliff-walking',4,'Почему Q-learning может выбирать путь ближе к обрыву?','Его цель предполагает лучший следующий ход','Он не умеет выбирать действия','Он использует только текстовые данные','Он не учитывает состояния'),
('sarsa-cliff-walking',5,'Что важно учитывать при сравнении SARSA и Q-learning?','Качество поведения во время обучения и финальную политику','Только цвет интерфейса','Только размер базы данных','Только число статей'),
('dqn-preprocessing',1,'Зачем уменьшать и нормализовать входные кадры?','Чтобы снизить сложность входа и стабилизировать обучение','Чтобы удалить все действия','Чтобы отключить replay buffer','Чтобы заменить награду текстом'),
('dqn-preprocessing',2,'Почему DQN часто получает стек кадров?','Один кадр не всегда показывает движение','Так проще хранить пароли','Так gamma становится нулевым','Так исчезают все состояния'),
('dqn-preprocessing',3,'Что может случиться при плохой предобработке?','Обучение станет нестабильным или слишком медленным','Алгоритм автоматически станет PPO','Все тесты пройдут сами','Среда перестанет выдавать действия'),
('dqn-preprocessing',4,'Что важно для марковского состояния?','Оно должно содержать достаточно информации для решения','Оно должно быть только изображением','Оно не должно включать признаки','Оно всегда состоит из одного числа'),
('dqn-preprocessing',5,'Как помогают рекуррентные сети или история наблюдений?','Компенсируют недостающую информацию о прошлом','Удаляют функцию ценности','Запрещают исследование','Заменяют actor'),
('dqn-improvements',1,'Зачем нужен Double DQN?','Чтобы уменьшить переоценку Q-значений','Чтобы удалить target network','Чтобы сделать все действия случайными','Чтобы заменить DQN на MDP'),
('dqn-improvements',2,'Как Double DQN разделяет обновление?','Online-сеть выбирает действие, target-сеть оценивает','Одна сеть удаляет награды, другая состояния','Actor выбирает тему сайта','Critic хранит пароль'),
('dqn-improvements',3,'Что разделяет Dueling DQN?','Ценность состояния и преимущество действий','Пользователей и администраторов','Случайные и текстовые награды','Только статьи и тесты'),
('dqn-improvements',4,'Когда dueling-архитектура особенно полезна?','Когда многие действия в состоянии похожи по эффекту','Когда нет состояний','Когда нет нейросети','Когда все награды отрицательные'),
('dqn-improvements',5,'С чем обычно сочетаются Double и Dueling DQN?','С replay buffer и target network','С отключением обучения','С ручной проверкой каждого пикселя','С удалением TD-цели'),
('actor-critic-policy-gradient',1,'Что напрямую обучает градиент стратегии?','Вероятности действий в политике','Только таблицу переходов среды','Только список пользователей','Только размер replay buffer'),
('actor-critic-policy-gradient',2,'Что происходит с вероятностью хорошего действия?','Она должна увеличиваться','Она всегда становится нулевой','Она удаляется из модели','Она заменяется gamma'),
('actor-critic-policy-gradient',3,'Зачем нужен baseline?','Чтобы уменьшить дисперсию оценки градиента','Чтобы запретить critic','Чтобы заменить состояние','Чтобы сделать reward строкой'),
('actor-critic-policy-gradient',4,'Что часто выступает baseline в actor-critic?','Функция ценности V(s)','Пароль администратора','Случайный номер вопроса','Список статей'),
('actor-critic-policy-gradient',5,'Где особенно полезен градиент стратегии?','В задачах с непрерывными действиями','Только в табличном лабиринте','Только при известной модели P','Только без наград'),
('actor-critic-ppo-a2c',1,'Что означает A2C?','Advantage Actor-Critic','Automatic Action Counter','Adaptive Article Course','Advanced Answer Check'),
('actor-critic-ppo-a2c',2,'Что использует actor в A2C для обновления?','Оценку преимущества','Только название состояния','Только максимальный Q из таблицы','Только последнюю статью'),
('actor-critic-ppo-a2c',3,'Главная идея PPO?','Не менять политику слишком резко','Всегда делать случайные действия','Удалить critic','Хранить только одну награду'),
('actor-critic-ppo-a2c',4,'Зачем PPO ограничивает обновление политики?','Чтобы сохранить стабильность обучения','Чтобы отключить тесты','Чтобы убрать состояния','Чтобы сделать gamma отрицательным'),
('actor-critic-ppo-a2c',5,'Для каких задач часто подходят A2C и PPO?','Для больших или непрерывных пространств действий','Только для одной клетки grid world','Только для статей без тестов','Только для задач без стратегии');

INSERT INTO questions (test_id, question_text, question_type, sort_order)
SELECT tests.id, expanded_questions.question_text, 'single_choice', expanded_questions.sort_order
FROM expanded_questions
JOIN subtopics ON subtopics.slug = expanded_questions.subtopic_slug
JOIN tests ON tests.subtopic_id = subtopics.id
ON CONFLICT (test_id, sort_order) DO UPDATE SET question_text = EXCLUDED.question_text;

CREATE TEMP TABLE expanded_options AS
SELECT subtopic_slug, sort_order AS question_order, 1 AS option_order, correct AS option_text, TRUE AS is_correct FROM expanded_questions
UNION ALL SELECT subtopic_slug, sort_order, 2, wrong_1, FALSE FROM expanded_questions
UNION ALL SELECT subtopic_slug, sort_order, 3, wrong_2, FALSE FROM expanded_questions
UNION ALL SELECT subtopic_slug, sort_order, 4, wrong_3, FALSE FROM expanded_questions;

INSERT INTO answer_options (question_id, option_text, is_correct, sort_order)
SELECT questions.id, expanded_options.option_text, expanded_options.is_correct, expanded_options.option_order
FROM expanded_options
JOIN subtopics ON subtopics.slug = expanded_options.subtopic_slug
JOIN tests ON tests.subtopic_id = subtopics.id
JOIN questions ON questions.test_id = tests.id AND questions.sort_order = expanded_options.question_order
ON CONFLICT (question_id, sort_order) DO UPDATE SET
  option_text = EXCLUDED.option_text,
  is_correct = EXCLUDED.is_correct;

INSERT INTO ontology_concepts (slug, name, description, complexity)
VALUES
  ('return', 'Возврат', 'Суммарная дисконтированная награда от текущего момента.', 2),
  ('model-based', 'Модельное обучение', 'Подход, использующий известную или обученную модель переходов и наград.', 3),
  ('model-free', 'Безмодельное обучение', 'Подход, который учится по опыту без явной модели среды.', 3),
  ('learning-rate', 'Скорость обучения', 'Параметр alpha, управляющий размером обновления оценок.', 3),
  ('on-policy', 'On-policy обучение', 'Оценивание той политики, которая используется для сбора опыта.', 4),
  ('preprocessing', 'Предобработка состояния', 'Подготовка наблюдений перед подачей в модель.', 4),
  ('double-dqn', 'Double DQN', 'Улучшение DQN, уменьшающее переоценку Q-значений.', 5),
  ('policy-gradient', 'Градиент стратегии', 'Метод прямой оптимизации параметризованной политики.', 5),
  ('ppo', 'PPO', 'Actor-critic алгоритм со стабильным ограниченным обновлением политики.', 5)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  complexity = EXCLUDED.complexity;

INSERT INTO ontology_relations (source_concept_id, target_concept_id, relation_type)
SELECT source.id, target.id, relation_type
FROM (
  VALUES
    ('return','reward','requires'),
    ('return','policy','requires'),
    ('model-based','mdp','requires'),
    ('model-free','mdp','requires'),
    ('learning-rate','td-learning','requires'),
    ('on-policy','policy','requires'),
    ('on-policy','td-learning','requires'),
    ('preprocessing','dqn','requires'),
    ('double-dqn','dqn','requires'),
    ('policy-gradient','policy','requires'),
    ('ppo','actor-critic','requires'),
    ('ppo','policy-gradient','requires')
) AS relation_data(source_slug, target_slug, relation_type)
JOIN ontology_concepts source ON source.slug = relation_data.source_slug
JOIN ontology_concepts target ON target.slug = relation_data.target_slug
ON CONFLICT (source_concept_id, target_concept_id, relation_type) DO NOTHING;

INSERT INTO subtopic_concepts (subtopic_id, concept_id, weight)
SELECT subtopics.id, ontology_concepts.id, concept_data.weight
FROM (
  VALUES
    ('mdp-policy-return','return',5),
    ('mdp-policy-return','policy',4),
    ('mdp-model-free-model-based','model-based',4),
    ('mdp-model-free-model-based','model-free',5),
    ('q-learning-parameters','learning-rate',4),
    ('q-learning-parameters','exploration',4),
    ('q-learning-practice','q-learning',5),
    ('q-learning-practice','td-learning',4),
    ('sarsa-on-policy','on-policy',5),
    ('sarsa-on-policy','sarsa',5),
    ('sarsa-cliff-walking','sarsa',4),
    ('sarsa-cliff-walking','exploration',4),
    ('dqn-preprocessing','preprocessing',5),
    ('dqn-preprocessing','dqn',4),
    ('dqn-improvements','double-dqn',5),
    ('dqn-improvements','dqn',5),
    ('actor-critic-policy-gradient','policy-gradient',5),
    ('actor-critic-policy-gradient','actor-critic',4),
    ('actor-critic-ppo-a2c','ppo',5),
    ('actor-critic-ppo-a2c','actor-critic',5)
) AS concept_data(subtopic_slug, concept_slug, weight)
JOIN subtopics ON subtopics.slug = concept_data.subtopic_slug
JOIN ontology_concepts ON ontology_concepts.slug = concept_data.concept_slug
ON CONFLICT (subtopic_id, concept_id) DO UPDATE SET weight = EXCLUDED.weight;

INSERT INTO subtopic_keywords (subtopic_id, keyword)
SELECT subtopics.id, keyword_data.keyword
FROM (
  VALUES
    ('mdp-policy-return','возврат'), ('mdp-policy-return','стратегия'), ('mdp-policy-return','эпизод'),
    ('mdp-model-free-model-based','модель среды'), ('mdp-model-free-model-based','model-free'), ('mdp-model-free-model-based','планирование'),
    ('q-learning-parameters','alpha'), ('q-learning-parameters','epsilon'), ('q-learning-parameters','gamma'),
    ('q-learning-practice','Q-таблица'), ('q-learning-practice','TD-ошибка'), ('q-learning-practice','алгоритм'),
    ('sarsa-on-policy','on-policy'), ('sarsa-on-policy','безопасность'), ('sarsa-on-policy','SARSA'),
    ('sarsa-cliff-walking','Cliff Walking'), ('sarsa-cliff-walking','риск'), ('sarsa-cliff-walking','траектория'),
    ('dqn-preprocessing','предобработка'), ('dqn-preprocessing','кадры'), ('dqn-preprocessing','состояние'),
    ('dqn-improvements','Double DQN'), ('dqn-improvements','Dueling DQN'), ('dqn-improvements','переоценка'),
    ('actor-critic-policy-gradient','policy gradient'), ('actor-critic-policy-gradient','baseline'), ('actor-critic-policy-gradient','преимущество'),
    ('actor-critic-ppo-a2c','A2C'), ('actor-critic-ppo-a2c','PPO'), ('actor-critic-ppo-a2c','стабильность')
) AS keyword_data(subtopic_slug, keyword)
JOIN subtopics ON subtopics.slug = keyword_data.subtopic_slug
ON CONFLICT (subtopic_id, keyword) DO NOTHING;
